export default "// Original Pearl Cloud fluid-film material, shared by Studio and native OpenGL.\n// The vector field is deterministic: only supplied audio features and phase move it.\nvec3 pearlFlow(vec2 p, float phase, float seed) {\n    vec2 q=p;\n    vec2 dx=vec2(1.,0.),dy=vec2(0.,1.);\n    for(int j=0;j<7;j++) {\n        float i=float(j);\n        float a=1.35+i*.31;\n        float b=.44/(1.+i*.27);\n        float ax=q.y*a+seed*.81+phase*(.11+i*.018);\n        float ay=q.x*a-seed*.63-phase*(.13-i*.012);\n        vec2 nx=dx+b*vec2(cos(ax)*a*dx.y,-sin(ay)*a*dx.x);\n        vec2 ny=dy+b*vec2(cos(ax)*a*dy.y,-sin(ay)*a*dy.x);\n        q+=b*vec2(sin(ax),cos(ay));\n        mat2 r=mat2(.8,.6,-.6,.8);\n        q=r*q*1.18;dx=r*nx*1.18;dy=r*ny*1.18;\n    }\n    float f=q.x+.55*q.y;\n    return vec3(f,dx.x+.55*dx.y,dy.x+.55*dy.y);\n}\nvec3 renderPearlCloud(vec2 uv, vec3 background,vec3 colourA,vec3 colourB,vec3 colourC,\n vec3 energy,float phase,float gain,float aspect,int theme,vec2 viewportSize) {\n    vec3 a=clamp(colourA,0.,1.),b=clamp(colourB,0.,1.),c=clamp(colourC,0.,1.);\n    vec3 drive=clamp(energy*clamp(gain,.25,4.),0.,1.5);\n    float ratio=clamp(aspect,.25,8.);\n    float fit=.84*min(ratio/1.06,1./.64);\n    vec2 p=(uv-.5)*vec2(2.*ratio,2.)/fit;\n    if(abs(p.x)>=1.06||abs(p.y)>=.64)return background;\n    float support=(1.-smoothstep(.94,1.06,abs(p.x)))*(1.-smoothstep(.52,.64,abs(p.y)));\n    float pixel=2./max(1.,viewportSize.y*fit);\n    vec3 outColour=background;\n    float haze=exp(-dot(p*vec2(1.4,2.1),p*vec2(1.4,2.1))*2.4);\n    outColour=mix(outColour,mix(b,c,.6),haze*(theme==1?.18:.10));\n    for(int k=0;k<5;k++) {\n       float i=float(k),depth=i/4.;\n       float seed=i*.65;\n       vec2 fieldScale=vec2(3.1,3.6)*(1.+.10*drive.y);\n       vec2 q=p*fieldScale;\n       q.x+=.22*sin(phase*.13+i*.5);\n       q.y+=.15*cos(phase*.17+i*.7);\n       vec3 flow=pearlFlow(q,phase,seed);\n       float f=flow.x;\n       vec2 grad=flow.yz*fieldScale;\n       float ridge=f*3.6+i*.65;\n       float curl=.5+.5*sin(ridge);\n       float w=.30+.13*drive.x;\n       float centre=.12*sin(p.x*3.4+seed*1.5+phase*.12);\n       vec2 envelope=vec2(p.x/(.80+.08*sin(i)),(p.y-centre)/(w+.04*cos(i)));\n       float shape=1.-smoothstep(.46,1.06,dot(envelope,envelope)+.10*sin(f*1.1+i));\n       float hole=smoothstep(.02,.24,abs(f*.25+.11*sin(p.x*8.+seed)));\n       float film=pow(curl,5.0)*shape*mix(.55,1.,hole);\n       float dust=pow(curl,.7)*shape*.022;\n       float heightSlope=cos(ridge)*3.6;\n       vec3 n=normalize(vec3(-grad*heightSlope*.11,1.));\n       vec3 l=normalize(vec3(-.5,.85,1.2));\n       vec3 halfLight=normalize(l+vec3(0.,0.,1.));\n       float diffuse=max(0.,dot(n,l));\n       float fresnel=pow(1.-max(0.,n.z),2.);\n       float spec=pow(max(0.,dot(n,halfLight)),32.);\n       float optical=.5+.5*sin(f*.42+i*.9+n.y*2.4);\n       vec3 dye=mix(a,b,smoothstep(.10,.78,optical));\n       dye=mix(dye,c,smoothstep(.56,1.,optical)*.76);\n       vec3 col=dye*(.40+.63*diffuse);\n       col+=c*spec*.8+mix(b,c,.5)*fresnel*.23;\n       float stripe=f*14.+sin(f*2.2+i)*1.2;\n       float footprint=length(grad)*14.*pixel;\n       float fibres=pow(.5+.5*sin(stripe),16.)*(1.-smoothstep(.55,2.8,footprint));\n       col=mix(col,col*.65+a*.14,fibres*.35);\n       col+=c*fibres*(.05+.08*drive.z);\n       float edge=pow(curl,32.)*shape;\n       float opacity=clamp(film*(.65+.10*depth)+dust,0.,.84);\n       outColour=mix(outColour,col,opacity);\n       outColour+=mix(b,c,optical)*edge*(.023+.035*drive.z);\n    }\n    return mix(background,clamp(outColour,0.,1.),support);\n}\n";
